from pathlib import Path
import json, html, shutil, re
ROOT=Path(__file__).parent; SRC=ROOT/'src'; D=ROOT/'dist';
if D.exists(): shutil.rmtree(D)
A=D/'assets'; A.mkdir(parents=True,exist_ok=True)
for f in (SRC/'assets').iterdir():
 if f.is_file():shutil.copy2(f,A/f.name)
for name in ['styles.css','app.js','thread-motion.css','thread-motion.js']:shutil.copy2(SRC/name,A/name)
E=html.escape
products=json.loads((SRC/'products.json').read_text()); lookup={p['slug']:p for p in products}
meta={
'embroidered':('Thread you can feel.','Raised stitch texture','Bold shapes & lettering','Readability at the finished size','#f1d27c','#b64b2b'),
'woven':('Let the details speak.','Fine, flat thread surface','Detailed artwork & small lettering','Line weight and legibility','#c5d4ee','#29477b'),
'pvc':('A different dimension.','Molded, raised form','Defined shapes & dimensional design','Relief, color and attachment','#b8c5b0','#384d3f'),
'chenille':('Big on character.','Soft, plush texture','Bold letters & larger shapes','Space for the textured surface','#e7b7c0','#8a3044'),
'leather':('Quietly distinctive.','A material-led finish','Labels, apparel & accessories','Composition, finish and contrast','#d3ad7c','#65412b')}
mark=(SRC/'assets/mark.svg').read_text(); paths=re.search(r'<g[^>]*>(.*?)</g>',mark).group(1)

def specimen(k):
 bg,ink=meta[k][4:]; texture=''
 defs=f'''<defs><linearGradient id="edge" x2="0" y2="1"><stop stop-color="{bg}"/><stop offset="1" stop-color="{ink}"/></linearGradient><pattern id="stitch" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 0L5 5" stroke="white" stroke-opacity=".24" stroke-width="1"/><path d="M0 4L4 0" stroke="black" stroke-opacity=".09" stroke-width=".7"/></pattern><pattern id="weave" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M0 1H4M1 0V4" stroke="white" stroke-opacity=".35" stroke-width="1"/></pattern></defs>'''
 if k=='embroidered':
  art=f'<rect x="38" y="34" width="324" height="272" rx="60" fill="{ink}"/><rect x="47" y="43" width="306" height="254" rx="52" fill="{bg}"/><rect x="55" y="51" width="290" height="238" rx="44" fill="url(#stitch)" stroke="{ink}" stroke-width="3" stroke-dasharray="2 4"/><g transform="translate(119 75) scale(.445)" fill="{ink}">{paths}</g><text x="200" y="251" text-anchor="middle" fill="{ink}" font-size="17" font-weight="700" letter-spacing="2">PATCHSMITH</text>'
 elif k=='woven':
  art=f'<path d="M28 80H372V269H28Z" fill="{ink}"/><path d="M36 88H364V261H36Z" fill="{bg}"/><path d="M36 88H364V261H36Z" fill="url(#weave)"/><g transform="translate(63 121) scale(.32)" fill="{ink}">{paths}</g><text x="206" y="153" fill="{ink}" font-size="21" font-weight="700">PATCH</text><text x="206" y="180" fill="{ink}" font-size="21" font-weight="700">SMITH</text><path d="M207 193H327" stroke="{ink}"/><text x="207" y="216" fill="{ink}" font-size="10" letter-spacing="2">WOVEN STUDY</text>'
 elif k=='pvc':
  art=f'<rect x="61" y="27" width="278" height="286" rx="66" fill="#24352b"/><rect x="61" y="21" width="278" height="286" rx="66" fill="{ink}" stroke="#65816a" stroke-width="3"/><rect x="77" y="37" width="246" height="254" rx="52" fill="none" stroke="#24352b" stroke-width="6"/><g transform="translate(112 86) scale(.49)" fill="#25382b">{paths}</g><g transform="translate(112 80) scale(.49)" fill="{bg}">{paths}</g><path d="M116 256H284" stroke="{bg}" stroke-width="2"/>'
 elif k=='chenille':
  art=f'<path d="M100 30H255L318 91V188L252 250H188V314H91V30Z" fill="{ink}"/><path d="M103 42H250L306 96V181L247 238H176V302H103Z M176 106V172H226L241 157V122L225 106Z" fill="#f6ead6" fill-rule="evenodd"/><path d="M116 55H244L292 102V176L241 225H163V289H116Z M163 93V185H231L254 163V116L231 93Z" fill="{ink}" stroke="{bg}" stroke-width="4" stroke-dasharray="1 3" fill-rule="evenodd"/><path d="M116 55H244L292 102V176L241 225H163V289H116Z M163 93V185H231L254 163V116L231 93Z" fill="url(#stitch)" fill-rule="evenodd"/>'
 else:
  art=f'<rect x="23" y="74" width="354" height="214" rx="21" fill="{ink}"/><rect x="23" y="68" width="354" height="214" rx="21" fill="{bg}"/><rect x="34" y="79" width="332" height="192" rx="15" fill="none" stroke="{ink}" stroke-width="2" stroke-dasharray="4 5"/><g transform="translate(63 115) scale(.31)" fill="{ink}">{paths}</g><text x="201" y="153" fill="{ink}" font-size="20" font-weight="700">PATCHSMITH</text><path d="M203 169H338" stroke="{ink}"/><text x="203" y="193" fill="{ink}" font-size="10" letter-spacing="2">MATERIAL STUDY</text>'
 return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 340" role="img"><title>{k.title()} patch concept</title>{defs}<g font-family="Arial,sans-serif">{art}</g></svg>'
for p in products:(A/(p['slug']+'-concept.svg')).write_text(specimen(p['slug']))
shutil.copy2(A/'mark.svg',A/'favicon.svg')

def btn(label,href,cls=''):
 return f'<a class="button {cls}" href="{href}">{label}<span aria-hidden="true">↗</span></a>'
def eyebrow(label):return f'<p class="eyebrow">{label}</p>'
def page_intro(label,title,lead):return f'<section class="page-intro wrap">{eyebrow(label)}<h1>{title}</h1><p class="lead">{lead}</p></section>'
def logo(light=False):return f'<span class="brand brand-exact"><img src="/assets/brand-horizontal{"-light" if light else ""}.svg" alt="PATCHSMITH" width="210" height="43"></span>'
def cta():return f'<section class="big-cta"><div class="wrap"><p class="eyebrow">Your idea. The next detail.</p><h2>Let’s make<br>your mark.</h2>{btn("Build your project brief","/request-a-quote/","cream")}<p class="small">A guided starting point. No payment or commitment.</p></div><span class="cta-star" aria-hidden="true">✳</span></section>'
navs=[('/patches/','The patches'),('/how-it-works/','The process'),('/about/','Our approach')]

def shell(route,title,desc,body):
 links=''.join(f'<a href="{u}"'+(' aria-current="page"' if route==u or (u=='/patches/' and route.startswith(u)) else '')+f'>{t}</a>' for u,t in navs)
 footlinks=''.join(f'<a href="/patches/{p["slug"]}/">{p["name"]}</a>' for p in products)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f0e7"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; font-src 'self'; connect-src 'none'; form-action 'none'; base-uri 'self'; object-src 'none'"><meta name="robots" content="noindex,nofollow"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/SpaceGrotesk-Variable.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/styles.css"><link rel="stylesheet" href="/assets/thread-motion.css"><script src="/assets/app.js" defer></script><script src="/assets/thread-motion.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="preview-bar"><span>PRIVATE DESIGN PREVIEW</span><span>Forms stay on your device. Nothing is sent.</span></div><header class="site-header"><div class="header-inner wrap"><a class="home-link" href="/" aria-label="PATCHSMITH home">{logo()}</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="main-nav">Menu <span aria-hidden="true">＋</span></button><nav id="main-nav" class="nav" aria-label="Main navigation">{links}<a class="nav-secondary" href="/faq/">FAQ</a><a class="nav-secondary" href="/contact/">Contact</a>{btn('Start a project','/request-a-quote/','small-button')}</nav></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap"><div class="footer-top"><div>{logo(True)}<p>Made in Pakistan.<br>Made for brands worldwide.</p></div><div><p class="eyebrow">Find your feel</p>{footlinks}</div><div><p class="eyebrow">Keep exploring</p><a href="/how-it-works/">The process</a><a href="/about/">Our approach</a><a href="/faq/">Good questions</a><a href="/contact/">Contact</a><a href="/request-a-quote/">Build a brief ↗</a></div></div><div class="footer-word" aria-hidden="true">PATCHSMITH</div><div class="footer-bottom"><span>© 2026 PATCHSMITH</span><span>Owner-review prototype · All patch artwork is conceptual</span><a href="#main">Back to top ↑</a></div></div></footer></body></html>'''
pages=[]
def page(route,title,desc,body):
 path=D/route.strip('/')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(shell(route,title,desc,body));pages.append({'route':route,'title':title,'description':desc})

def materials():
 tabs=''.join(f'<button type="button" id="tab-{p["slug"]}" role="tab" aria-controls="panel-{p["slug"]}" aria-selected="{"true" if i==0 else "false"}" tabindex="{0 if i==0 else -1}" data-material="{p["slug"]}"><span>0{i+1}</span>{p["name"]}</button>' for i,p in enumerate(products))
 panels=''
 for i,p in enumerate(products):
  k=p['slug']; m=meta[k]
  panels+=f'''<div class="material-panel" id="panel-{k}" role="tabpanel" aria-labelledby="tab-{k}" tabindex="0" {"hidden" if i else ""}><div class="material-stage stage-{k}"><span class="spec-label">MATERIAL STUDY / 0{i+1}</span><img src="/assets/{k}-concept.svg" alt="{p['name']} patch illustration using the PATCHSMITH identity" width="400" height="340" loading="lazy"><span class="stage-caption">Original illustration · Not a production sample</span><span class="stage-cross" aria-hidden="true">＋</span></div><div class="material-copy"><p class="eyebrow">{p['name']} patches</p><h3>{m[0]}</h3><p>{p['intro']}</p><dl class="spec-list"><div><dt>The feel</dt><dd>{m[1]}</dd></div><div><dt>Consider for</dt><dd>{m[2]}</dd></div><div><dt>Discuss first</dt><dd>{m[3]}</dd></div></dl><div class="actions">{btn('Choose '+p['name'].lower(),'/request-a-quote/?type='+k)}<a class="text-link" href="/patches/{k}/">Explore the details ↗</a></div></div></div>'''
 rows=''.join(f'<tr><th scope="row"><a href="/patches/{p["slug"]}/">{p["name"]} ↗</a></th><td>{meta[p["slug"]][1]}</td><td>{meta[p["slug"]][2]}</td><td>{meta[p["slug"]][3]}</td></tr>' for p in products)
 return f'''<section id="materials" class="section wrap material-section"><div class="section-heading"><div>{eyebrow('01 / Find your feel')}<h2>Same idea.<br>Different character.</h2></div><p>Five ways to make your mark. Switch the material to see what changes.</p></div><div class="material-tabs" role="tablist" aria-label="Explore patch materials">{tabs}</div>{panels}<details class="compare"><summary>Compare all five materials <span aria-hidden="true">＋</span></summary><div class="table-scroll" role="region" aria-label="Material comparison" tabindex="0"><table><caption>A starting point for your brief. Final suitability depends on artwork, size and specification.</caption><thead><tr><th>Material</th><th>Feel</th><th>Consider for</th><th>Review together</th></tr></thead><tbody>{rows}</tbody></table></div></details><noscript><p>JavaScript is off. Use the comparison and individual material pages to explore all five styles.</p></noscript></section>'''

def uses():
 return f'''<section id="applications" class="use-section"><div class="wrap use-layout"><div>{eyebrow('02 / Give it a purpose')}<h2>Where will<br>yours go?</h2><p>The right patch starts with what it needs to do. Pick a starting point.</p><div class="use-options" role="group" aria-label="Choose an application"><button type="button" data-use="Apparel brands" aria-pressed="true">Apparel brands <span>↗</span></button><button type="button" data-use="Teams and clubs" aria-pressed="false">Teams &amp; clubs <span>↗</span></button><button type="button" data-use="Workwear" aria-pressed="false">Workwear <span>↗</span></button><button type="button" data-use="Merch and accessories" aria-pressed="false">Merch &amp; accessories <span>↗</span></button></div></div><div class="use-result" aria-live="polite" aria-atomic="true"><span class="small-label">A STARTING POINT, NOT A FINAL SPEC</span><span class="use-symbol" aria-hidden="true">↗</span><p class="eyebrow" id="use-label">Apparel brands</p><h3 id="use-title">Give the garment<br>its signature.</h3><p id="use-copy">Start with the garment, placement and artwork. A finer label and a statement patch can call for very different finishes.</p><div class="use-tags" id="use-tags"><span>Woven</span><span>Embroidered</span><span>Leather</span></div><p class="small" id="use-check">Bring: fabric type, placement and your intended care requirements.</p><a class="button dark" id="use-cta" href="/request-a-quote/?use=Apparel%20brands&amp;type=woven">Build this brief <span aria-hidden="true">↗</span></a></div></div></section>'''
process_items=[('The idea','Share the artwork and context.','Tell us what the patch is for, the size you have in mind and your preferred material. Unknowns can stay open in your initial brief.'),('The specification','Turn the idea into a clear plan.','Review material, dimensions, color, edge and backing. Confirm pricing, quantities and timing in the quote before making a commitment.'),('The approval','Know what you are approving.','Review the agreed artwork and specification before production. Any proof, sample and revision arrangements must be confirmed for your project.'),('The production','Make it. Check it. Send it.','Production and delivery follow the approved project terms. The schedule, destination and shipping arrangements should be agreed before the order is placed.')]
def process():
 rows=''.join(f'<details class="process-row" {"open" if i==0 else ""}><summary><span class="step-number">0{i+1}</span><span>{title}</span><span class="process-plus" aria-hidden="true">＋</span></summary><div><h3>{heading}</h3><p>{body}</p></div></details>' for i,(title,heading,body) in enumerate(process_items))
 return f'<section id="process" class="section wrap process-section"><div class="section-heading"><div>{eyebrow("03 / Know what’s next")}<h2>A clear path.<br>A considered patch.</h2></div><p>From first idea to the final detail. Here’s what each conversation needs to resolve.</p></div><div class="process-layout"><div class="process-art"><img src="/assets/stitched-mark.webp" alt="Approved Sunset stitched PATCHSMITH interlock identity concept" width="1254" height="1254" loading="lazy"><span>SUNSET / STITCHED IDENTITY CONCEPT</span></div><div class="process-list">{rows}</div></div></section>'



def thread_transition(key,tight=False):
 def svg(mobile=False):
  ident='thread-sunset-'+key+('-mobile' if mobile else '-desktop')
  width=400 if mobile else 1200
  line='M0 25C65 25 70 105 150 105C230 105 245 20 290 20C330 20 350 60 315 75C280 90 270 55 310 55H330' if mobile else 'M0 80C180 80 140 140 300 140C440 140 480 25 600 25C690 25 730 100 660 110C590 120 560 70 630 70H810'
  stitches='M330 55C365 55 363 105 400 105' if mobile else 'M810 70C970 70 970 130 1200 130'
  return f'''<svg class="thread-{'mobile' if mobile else 'desktop'}" viewBox="0 0 {width} 160" preserveAspectRatio="none" aria-hidden="true" focusable="false"><defs><linearGradient id="{ident}" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="{width}" y2="0"><stop offset="0" stop-color="#7022b5"/><stop offset=".42" stop-color="#c21591"/><stop offset=".72" stop-color="#f02d59"/><stop offset="1" stop-color="#df5c0b"/></linearGradient></defs><path class="thread-line" d="{line}" pathLength="1" stroke="url(#{ident})"/><path class="thread-stitches" d="{stitches}" stroke="url(#{ident})"/></svg>'''
 return '<div class="thread-transition'+(' thread-transition--tight' if tight else '')+'" data-thread-motion aria-hidden="true">'+svg()+svg(True)+'</div>'

def story():
 garments=json.loads((SRC/'garments.json').read_text()); first=garments[0]
 swatches=''.join(f'<button type="button" data-garment-src="/assets/{E(g["file"])}" data-garment-name="{E(g["name"])}" data-garment-alt="{E(g["alt"])}" aria-pressed="{"true" if i==0 else "false"}"><span aria-hidden="true" style="background:{E(g["color"])}"></span>{E(g["name"])}</button>' for i,g in enumerate(garments))
 return f'''<section class="story-section wrap" id="our-story"><figure class="story-image"><img id="garment-image" src="/assets/{E(first['file'])}" alt="{E(first['alt'])}" width="1254" height="1254" loading="lazy"><figcaption><span>REPRESENT / <span lang="ur" dir="rtl">پاکستان</span></span><span>Concept design</span></figcaption><div class="garment-options" role="group" aria-label="Sweatshirt concept colors">{swatches}</div><span id="garment-status" class="sr-only" role="status">Showing {E(first['name'])} concept</span></figure><div class="story-copy">{eyebrow('The place behind the patch')}<h2>Something worth<br><em>representing.</em></h2><p>For Bilal Maqsood, PATCHSMITH is a way to put Pakistani craftsmanship in front of the world.</p><p>The ambition is simple: thoughtful design, careful embroidery and work that reflects well on where it is made. A small detail can carry that bigger purpose.</p><span class="story-signature">PAKISTAN / THE PLACE BEHIND THE WORK</span><a class="text-link" href="/about/">The story and the intention ↗</a></div></section>'''

hero=f'''<section class="hero wrap"><div class="hero-copy">{eyebrow('Custom patches / Made in Pakistan → Worldwide')}<h1>Make your<br>brand <em>felt.</em></h1><p class="hero-lead">Small detail. Big character.<br>Custom patches for brands, teams<br class="desktop-break"> and businesses with something to say.</p><div class="actions">{btn('Find your patch','#materials')}<a class="text-link" href="/request-a-quote/">Already have a brief? ↗</a></div></div><div class="hero-art" aria-label="Original PATCHSMITH material concept collection"><span class="art-index">THE DETAIL MAKES<br>THE DIFFERENCE.</span><div class="hero-grid" aria-hidden="true"></div><img class="hero-patch hero-patch-one" src="/assets/embroidered-concept.svg" alt="Golden embroidered patch concept with rust PS interlock" width="400" height="340" fetchpriority="high"><img class="hero-patch hero-patch-two" src="/assets/pvc-concept.svg" alt="Green dimensional PVC patch concept with PS interlock" width="400" height="340"><img class="hero-patch hero-patch-three" src="/assets/woven-concept.svg" alt="Blue woven label concept using the PATCHSMITH identity" width="400" height="340"><span class="art-orbit" aria-hidden="true">✳</span><span class="art-note">MATERIAL STUDIES, NOT PRODUCTION SAMPLES</span></div></section><nav class="journey-bar wrap" aria-label="Explore the page"><a href="#materials"><span>01</span> Find your feel <b>↓</b></a><a href="#applications"><span>02</span> Give it a purpose <b>↓</b></a><a href="#process"><span>03</span> Know what’s next <b>↓</b></a></nav><section class="manifesto wrap"><p>Not just a logo on a surface.<br>A detail people <em>connect with.</em></p><span>From clothing labels to team identity.<br>Built around your artwork and application.</span></section>'''
page('/','PATCHSMITH — Make your brand felt.','Explore five custom patch styles, compare materials and build a project brief. Made in Pakistan for brands worldwide.',hero+thread_transition('story',True)+story()+materials()+uses()+thread_transition('craft')+process()+cta())
page('/patches/','Find your feel — PATCHSMITH patches','Compare embroidered, woven, PVC, chenille and leather patch styles.',page_intro('The material studio','Five ways.<br>Your mark.','Start with the feeling you want to create. Then match the material to the artwork, size and application.')+materials()+uses()+cta())
for i,p in enumerate(products):
 k=p['slug'];m=meta[k]
 nextp=lookup[p['next']]
 body=f'''<div class="wrap breadcrumb"><a href="/patches/">The patches</a><span>/</span>{p['name']}</div><section class="product-hero wrap"><div class="product-intro">{eyebrow(f'Material 0{i+1} / 05')}<h1>{p['name']}<br><em>patches.</em></h1><p class="lead">{m[0]}</p><p>{p['intro']}</p>{btn('Build a '+p['name'].lower()+' brief','/request-a-quote/?type='+k)}</div><div class="material-stage stage-{k}"><span class="spec-label">A CLOSER LOOK / {p['name'].upper()}</span><img src="/assets/{k}-concept.svg" alt="{p['name']} PATCHSMITH patch concept illustration" width="400" height="340"><span class="stage-caption">Original concept · Not a production sample</span></div></section><section class="section wrap detail-layout"><h2>{p['heading']}</h2><div><p class="lead">{p['body']}</p><dl class="spec-list"><div><dt>Character</dt><dd>{m[1]}</dd></div><div><dt>Consider for</dt><dd>{p['consider']}</dd></div><div><dt>Review first</dt><dd>{m[3]}</dd></div></dl><details class="faq-item"><summary>{p['question']}<span aria-hidden="true">＋</span></summary><p>{p['answer']}</p></details></div></section><section class="wrap related-strip"><div>{eyebrow('Keep your options open')}<h2>Also consider<br>{nextp['name'].lower()}.</h2></div><img src="/assets/{nextp['slug']}-concept.svg" alt="{nextp['name']} patch concept" width="240" height="204" loading="lazy">{btn('Explore '+nextp['name'].lower(),'/patches/'+nextp['slug']+'/','outline')}</section>'''
 page('/patches/'+k+'/',p['name']+' patches — PATCHSMITH',p['intro'],body+cta())
page('/how-it-works/','From idea to patch — PATCHSMITH','Understand the brief, specification, approval and production stages of a custom patch project.',page_intro('The process','Good details.<br>Clear decisions.','A useful brief is the beginning. An agreed specification is what moves the project forward.')+process()+f'<section class="wrap brief-check section"><h2>Bring what you know.</h2><div><p>You don’t need every answer to begin. These details make the next conversation more useful.</p><ul class="check-list"><li>Your artwork or a description of the idea</li><li>Where the patch will go</li><li>Approximate dimensions and quantity</li><li>Preferred material and attachment</li><li>Delivery destination and any required date</li></ul>{btn("Build your brief","/request-a-quote/")}</div></section>'+cta())
page('/about/','The detail matters — About PATCHSMITH','PATCHSMITH creates custom patches in Pakistan for brands, teams and businesses worldwide.',page_intro('Our approach','The smallest detail<br>can say <em>the most.</em>','PATCHSMITH is about helping brands, teams and businesses turn an identity into something tangible.')+thread_transition('origin',True)+story()+f'<section class="about-band"><div class="wrap about-layout"><div>{eyebrow("Pakistan → Worldwide")}<h2>Made here.<br>Worn anywhere.</h2><p>Custom patches made in Pakistan for projects around the world, including US brands and businesses.</p><p>From the surface you choose to the way a patch attaches, each detail deserves a place in the conversation.</p></div><img src="/assets/stitched-mark.webp" alt="Selected Sunset stitched PATCHSMITH A interlock brand concept" width="1254" height="1254" loading="lazy"></div></section><section class="section wrap"><div class="section-heading"><h2>Our starting points.</h2><p>Three principles to build a better brief around.</p></div><div class="principles"><article><span>01</span><h3>Material has<br>a personality.</h3><p>Texture, dimension and finish all change how a design feels. Choose them deliberately.</p></article><article><span>02</span><h3>Context comes<br>before specification.</h3><p>A cap, a jacket and a work bag ask different things of a patch. Start with the application.</p></article><article><span>03</span><h3>Clarity belongs<br>in the details.</h3><p>Artwork, construction and project terms should be understood before production begins.</p></article></div></section>'+cta())
faqs=[('Materials','Which material should I choose?','Start with the material explorer and your intended use. Embroidered, woven, PVC, chenille and leather each create a different surface. The final choice should be checked against your artwork and finished dimensions.'),('Materials','Can a small logo or fine lettering work?','Share the artwork at the size you intend to use. Readability depends on material, line weight, lettering and construction. Highlight any detail that must stay intact.'),('Project details','What dimensions and quantity should I provide?','Include your intended width and height, the units you are using and the number of patches you are considering. Exact minimums and pricing must be confirmed in the quote; the brief does not establish a minimum order.'),('Project details','What backing options are available?','Tell us how the patch will be used and whether you prefer sew-on, heat-applied, hook-and-loop or another attachment. These are preferences to discuss; availability and suitability must be confirmed for the material and item.'),('Project details','Can I share a deadline?','Yes. Include a required date and delivery destination in your brief. Production and delivery timing must be confirmed before an order is placed. This preview does not promise a turnaround time.'),('Ordering','What happens before production?','The artwork, dimensions, material, attachment and commercial terms should be reviewed and approved. Proof, sample and revision arrangements must be agreed for your specific project.'),('Ordering','Where are the patches made and shipped?','PATCHSMITH patches are made in Pakistan and shipped worldwide. Destination-specific shipping arrangements, charges and any import requirements must be confirmed in the quote.'),('This preview','Does the project form send a request?','No. It builds a local, reviewable brief in your browser. You can download the text, but nothing is sent to PATCHSMITH. There are no payments, uploads or orders in this preview.'),('This preview','Are these real customer samples?','No. All patch artwork shown here is original conceptual illustration for the website design. It is not evidence of a finished production sample, customer project or specific manufacturing outcome.')]
faqrows=''.join(f'<details class="faq-item" data-faq-category="{cat}"><summary>{q}<span aria-hidden="true">＋</span></summary><p>{a}</p></details>' for cat,q,a in faqs)
page('/faq/','Good questions — PATCHSMITH FAQ','Answers about patch materials, preparing a brief and planning a project.',page_intro('Good questions','A little clarity.<br>A better starting point.','The useful questions before you choose a material or build your brief.')+f'<section class="wrap faq-section"><div class="faq-filters" role="group" aria-label="Filter questions">'+''.join(f'<button type="button" data-faq-filter="{c}" aria-pressed="{"true" if i==0 else "false"}">{c}</button>' for i,c in enumerate(['All','Materials','Project details','Ordering','This preview']))+f'</div><p class="small" id="faq-count" aria-live="polite">Showing all {len(faqs)} questions</p><div>{faqrows}</div></section>'+cta())
quote_options=''.join(f'<label class="material-choice"><input type="radio" name="patch" value="{p["slug"]}" required><img src="/assets/{p["slug"]}-concept.svg" alt="" width="120" height="102"><span>{p["name"]}</span><span class="choice-check" aria-hidden="true">✓</span></label>' for p in products)
quote=f'''{page_intro('Your project, one detail at a time','Let’s build<br>your brief.','Choose a starting point. Add what you know. Review everything before creating a local copy.')}<section class="quote-layout wrap"><aside class="quote-aside"><p class="eyebrow">Your progress</p><ol class="quote-progress"><li data-progress="0" aria-current="step"><span>01</span> The material</li><li data-progress="1"><span>02</span> The specification</li><li data-progress="2"><span>03</span> The project</li><li data-progress="3"><span>04</span> Your brief</li></ol><div class="quote-note"><span aria-hidden="true">↗</span><h3>A starting point.<br>No commitment.</h3><p>This is a local demo. Nothing is sent, uploaded or ordered. Your entries are not stored by this site.</p><a href="/faq/#main">Have a question? ↗</a></div></aside><div class="quote-main"><noscript><p class="form-error">This interactive brief needs JavaScript. You can still explore the materials and process using the navigation.</p></noscript><form id="quote-form" novalidate><div class="form-error" id="form-error" role="alert" hidden></div><section class="quote-step" data-step="0" aria-labelledby="step-heading-0"><p class="eyebrow">Step 01 / 04</p><h2 id="step-heading-0" tabindex="-1">Find the right feel.</h2><p>Choose an initial material. You can change it before creating your brief.</p><fieldset class="material-choices"><legend>Patch material <span>(required)</span></legend>{quote_options}</fieldset><div class="field"><label for="use">What is it for?</label><select id="use" name="use"><option value="">I’m still exploring</option><option>Apparel brands</option><option>Teams and clubs</option><option>Workwear</option><option>Merch and accessories</option><option>Another application</option></select></div><div class="form-actions"><a class="text-link" href="/patches/">Compare the materials ↗</a><button type="button" class="button" data-next>Next: the details <span aria-hidden="true">→</span></button></div></section><section class="quote-step" data-step="1" aria-labelledby="step-heading-1" hidden><p class="eyebrow">Step 02 / 04</p><h2 id="step-heading-1" tabindex="-1">Make it more specific.</h2><p>Leave anything undecided blank. Preferences are subject to material and project review.</p><div class="field"><label for="quantity">Planned quantity</label><input id="quantity" name="quantity" type="number" min="1" step="1" inputmode="numeric" placeholder="e.g. 250" aria-describedby="quantity-help"><p id="quantity-help" class="field-help">Your intended quantity, not a stated minimum order.</p></div><fieldset class="dimension-fields"><legend>Finished dimensions <span>(optional)</span></legend><div class="field"><label for="width">Width</label><input id="width" name="width" type="number" min="0.1" step="0.1" inputmode="decimal" placeholder="Width"></div><div class="field"><label for="height">Height</label><input id="height" name="height" type="number" min="0.1" step="0.1" inputmode="decimal" placeholder="Height"></div><div class="field"><label for="units">Units</label><select id="units" name="units"><option value="in">Inches</option><option value="cm">Centimeters</option><option value="mm">Millimeters</option></select></div></fieldset><div class="field"><label for="backing">Attachment preference</label><select id="backing" name="backing"><option value="">Help me decide</option>Sew-on</option><option>Heat-applied</option><option>Hook-and-loop</option><option>Another attachment</option></select><p class="field-help">Availability and suitability need confirmation for your chosen material and application.</p></div><div class="form-actions"><button type="button" class="text-button" data-back>← Back</button><button type="button" class="button" data-next>Next: your project <span aria-hidden="true">→</span></button></div></section><section class="quote-step" data-step="2" aria-labelledby="step-heading-2" hidden><p class="eyebrow">Step 03 / 04</p><h2 id="step-heading-2" tabindex="-1">Put it in context.</h2><div class="field"><label for="project">Project name <span>(required)</span></label><input id="project" name="project" required maxlength="120" placeholder="e.g. Fall collection labels" autocomplete="off"></div><div class="field-pair"><div class="field"><label for="country">Delivery country</label><input id="country" name="country" maxlength="100" placeholder="e.g. United States" autocomplete="country-name"></div><div class="field"><label for="needed">Needed-by date <span>(optional)</span></label><input id="needed" name="needed" type="date"><p class="field-help">A requested date, not a confirmed delivery date.</p></div></div><div class="field"><label for="notes">Artwork and project notes</label><textarea id="notes" name="notes" rows="5" maxlength="2500" placeholder="Describe your artwork, placement, colors or anything we should consider."></textarea><p class="field-help">This preview does not upload artwork. Please don’t enter sensitive information.</p></div><div class="form-actions"><button type="button" class="text-button" data-back>← Back</button><button type="button" class="button" data-next>Review your brief <span aria-hidden="true">→</span></button></div></section><section class="quote-step" data-step="3" aria-labelledby="step-heading-3" hidden><p class="eyebrow">Step 04 / 04</p><h2 id="step-heading-3" tabindex="-1">Your idea, in focus.</h2><p>Check your details. Nothing is submitted from this page.</p><div id="quote-summary"></div><div class="form-actions"><button type="button" class="text-button" data-back>← Back</button><button type="submit" class="button">Create local brief <span aria-hidden="true">↗</span></button></div><div class="brief-result" id="brief-result" role="status" hidden><h3>Your local brief is ready.</h3><p>Nothing has been sent to PATCHSMITH. Download a text copy for your records or edit your details.</p><button class="button dark" type="button" id="download-brief">Download brief (.txt) <span aria-hidden="true">↓</span></button></div></section></form></div></section>'''
page('/request-a-quote/','Build your project brief — PATCHSMITH','Explore material, specification and project details with a guided local brief builder. Nothing is sent from this preview.',quote)
contact=f'''{page_intro('Start a conversation','Got an idea?<br>Let’s give it shape.','If you know what you want, the project brief is the best starting point. For everything else, outline your question here.')}<section class="wrap contact-layout"><div class="contact-card">{eyebrow('A more useful starting point')}<h2>Bring your<br>next detail.</h2><p>Material, placement, artwork, quantity. A few details help frame the right conversation.</p>{btn('Build a project brief','/request-a-quote/')}<hr><p class="small">Made in Pakistan. Shipped worldwide.<br>Direct contact and collection details will be added before launch.</p></div><form id="contact-form" novalidate><p class="eyebrow">Local message preview</p><h2>What’s on your mind?</h2><p>This form does not send a message. It lets you prepare and review one on your device.</p><div class="field"><label for="contact-topic">Topic</label><select id="contact-topic" name="topic"><option>Choosing a patch material</option><option>Preparing artwork</option><option>Planning a project</option><option>Something else</option></select></div><div class="field"><label for="contact-message">Your question <span>(required)</span></label><textarea id="contact-message" name="message" rows="6" required maxlength="2500"></textarea></div><p id="contact-error" class="form-error" role="alert" hidden></p><button class="button" type="submit">Preview my message <span aria-hidden="true">↗</span></button><div id="contact-preview" class="brief-result" role="status" hidden><h3>Message preview only.</h3><p id="contact-preview-text"></p><p class="small">Nothing has been sent.</p></div></form></section>'''
page('/contact/','Your next detail — Contact PATCHSMITH','Prepare your question or start a guided PATCHSMITH project brief.',contact)
notfound=page_intro('404 / A loose thread','This page<br>came unstuck.','Let’s get you back to the patches.')+f'<div class="wrap notfound-actions">{btn("Back to the studio","/")}</div>'
(D/'404.html').write_text(shell('/404/','Page not found — PATCHSMITH','Return to the PATCHSMITH material studio.',notfound))
(D/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://patchsmith.co'+p['route']+'</loc></url>' for p in pages)+'</urlset>')
(D/'page-manifest.json').write_text(json.dumps(pages,indent=2))
print(f'Built {len(pages)} pages + 404 with local assets.')
# Refresh the portable page fragments and content references with this exact design.
R=ROOT/'review'; R.mkdir(exist_ok=True); W=R/'webflow-import'; W.mkdir(exist_ok=True)
for p in pages:
 route=p['route']; key='home' if route=='/' else route.strip('/').replace('/','__')
 source=(D/route.strip('/')/'index.html').read_text()
 content=source.split('<main id="main">',1)[1].split('</main>',1)[0]
 (W/(key+'.html')).write_text(content)
(R/'seo-manifest.json').write_text(json.dumps(pages,indent=2))
(R/'product-content.json').write_text(json.dumps(products,indent=2))

# Portable custom-code motion component for the native Webflow reconstruction.
for name in ['thread-motion.css','thread-motion.js']:shutil.copy2(SRC/name,W/name)
(W/'thread-transition-component.html').write_text(thread_transition('webflow-example'))
